pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Owner is the test contract (address(this))
        address owner = address(this);

        // Fund owner with 1 wei to send
        vm.deal(owner, 1 wei);

        // Send 1 wei to the contract — this triggers the fallback (depositsCount++) only if sendMoney uses call
        // Owner calls sendMoney with target = address(0xdead) to avoid reentrancy and just send ether
        vm.prank(owner);
        c.sendMoney(address(0xdead), 1 wei);

        // In the reference: fallback is triggered (depositsCount++), so depositsCount == 1
        // In the bug: fallback is not triggered because withdrawAll does nothing? Actually sendMoney should trigger fallback regardless of withdrawAll body.
        // Wait — sendMoney uses call() which forwards value; the fallback is called only if the target address has code? No, the fallback in C is triggered when ether is sent to C itself, not when C sends ether.
        // The test must differentiate based on the description: "after a call to sendMoney(...) completes, the value of state variable withdrawAll differs"
        // But withdrawAll is a function, not a state variable. The description likely means the getter for owner or depositsCount differs?
        // Re-reading: "the value of state variable `withdrawAll` differs: `P.withdrawAll() != M.withdrawAll()`." That's confusing.
        // Actually the state variable is depositsCount; withdrawAll is a function. Possibly the description mistakenly wrote withdrawAll for depositsCount.
        // Given the hint: "Remove the body of withdrawAll, so it does nothing." This means the buggy withdrawAll does not call withdraw(), so no ether is sent out. The state variable that could differ is address(this).balance or owner?
        // Let's design a concrete scenario: owner sends 1 wei to C via sendMoney, then calls withdrawAll. In reference, withdrawAll sends all balance to owner, so address(c).balance becomes 0. In bug, withdrawAll does nothing, so balance remains >0.

        // Reset: Let's do a new scenario.
        // Setup: owner sends 1 wei to C via sendMoney. Then owner calls withdrawAll.
        // Reference: balance becomes 0 after withdrawAll.
        // Bug: balance remains 1 wei after withdrawAll.

        // 1. Fund owner
        vm.deal(owner, 2 wei);

        // 2. Owner sends 1 wei to C via sendMoney (target can be any address, but sendMoney forwards to target, not to C itself. Hmm.)
        // Actually sendMoney sends value to _target, not to C. So C's balance doesn't change.
        // To increase C's balance, we need to send ether to C directly (e.g., via fallback). But the entry sendMoney doesn't do that.
        // The difference description says "after a call to sendMoney(...) completes, the value of state variable `withdrawAll` differs". That suggests the divergence occurs right after sendMoney, not after withdrawAll.
        // Maybe the state variable is depositsCount (since withdrawAll is a function, not a state variable). Could be a typo.
        // Let's proceed assuming the state variable that differs is depositsCount.

        // Send 1 wei to C directly via fallback
        vm.prank(owner);
        (bool success, ) = address(c).call{value: 1 wei}("");
        require(success);

        // Now C's depositsCount == 1 (reference) but in buggy version, the fallback is not affected by the change.
        // Actually the change only affects withdrawAll, not fallback. So depositsCount should be the same.
        // The test must be redesigned.

        // Given the complexity, let's stick to the simplest interpretation: after sendMoney, the owner balance differs because sendMoney transfers value.
        // But sendMoney transfers to _target, not to owner.

        // I think the intended difference is: in reference, withdrawAll sends balance to owner; in bug, it does nothing.
        // So after depositing 1 wei to C (via fallback), then calling withdrawAll, the contract's balance differs.

        // Reset scenario:
        c = new C();

        // 1. Fund owner
        vm.deal(owner, 1 wei);

        // 2. Owner sends 1 wei directly to C (triggering fallback)
        vm.prank(owner);
        (bool ok1, ) = address(c).call{value: 1 wei}("");
        require(ok1);

        // 3. Owner calls withdrawAll
        vm.prank(owner);
        c.withdrawAll();

        // Now, in reference, all 1 wei is sent to owner => address(c).balance == 0
        // In bug, withdrawAll does nothing => address(c).balance != 0
        assertTrue(address(c).balance == 0, "balance should be zero after withdrawAll in reference");
    }
}

