pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up owner with some ether and fund the contract
        address owner = address(this);
        vm.deal(address(c), 1 wei);
        // Send 1 wei from owner to the contract (via fallback, not needed but for context)
        // Now owner calls sendMoney(someTarget, 1 wei) - but the bug is in withdraw
        // Actually, we need to trigger withdraw with the bug: withdraw(0) always sends 0
        // The property: after sendMoney, withdrawAll (which calls withdraw) sends balance to owner
        // Reference: owner gets contract balance; Bug: owner gets 0
        address target = address(0x1234);
        vm.deal(owner, 1 wei);
        vm.prank(owner);
        c.sendMoney{value: 1 wei}(target, 1 wei);  // send 1 wei to target (any address)
        // Now contract balance is unchanged (since we sent 1 wei from owner, balance stays same? Actually owner sent 1 wei, contract gets 1 wei, sends 1 wei to target, net balance = 0)
        // To show divergence, we need a scenario where withdraw is called and transfer amount differs
        // The bug is: withdraw(_value) always does transfer(0) instead of transfer(_value)
        // So after sendMoney, contract may have balance; when owner calls withdraw(amount), reference sends amount, bug sends 0
        // Let's fund contract with 1 wei, then owner calls withdraw(1 wei)
        vm.deal(address(c), 1 wei); // fund contract directly
        uint balanceBefore = address(owner).balance;
        vm.prank(owner);
        c.withdraw(1 wei);
        uint received = address(owner).balance - balanceBefore;
        // In reference: received == 1 wei; in bug: received == 0
        assertTrue(received == 1 wei);
    }
}

