        address target = address(0xdead); // non-payable address, will fail on call
        uint value = 1 ether;

        // First call to sendMoney that will fail - reference reverts, bug does not
        // We need to catch the revert to observe the difference
        bool success;
        try c.sendMoney(target, value) {
            success = true;
        } catch {
            success = false;
        }

        // In the reference, the call fails and reverts, so depositsCount remains 0
        // In the bug, the call fails but does not revert, so depositsCount becomes 1
        // We assert that the reference behavior is depositsCount == 0 (i.e., revert happened)
        // The bug would have success == true and depositsCount == 1

        // To make the assertion pass on reference and fail on bug:
        // Assert that the transaction reverted (success == false) OR depositsCount == 0
        // But we want a concrete observable difference: depositsCount
        // So we assert that depositsCount is 0 (true for reference), which will be false for bug
        assertTrue(c.depositsCount() == 0);
    }
}
